public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]] = true;
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        for (int[] next : paths[current[0]]) {
            if (!visited[next[0]]) {
                visited[next[0]] = true;
                queue.offer(next);
                if (current[0] == end[0] && current[1] == end[1]) {
                    return "can be travelled";
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a set to keep track of the visited n-tersections
    Set<String> visited = new HashSet<>();
    // Add the starting n-tersection to the set
    visited.add(start[0] + "," + start[1]);
    // Create a queue to keep track of the n-tersections to visit
    Queue<int[]> queue = new ArrayDeque<>();
    // Add the starting n-tersection to the queue
    queue.offer(start);
    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.poll();
        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            // If it is, return "can be travelled"
            return "can be travelled";
        }
        // Loop through the paths between adjacent n-tersections
        for (int[] path : paths) {
            // Check if the current n-tersection has a path to the adjacent n-tersection
            if (path[0] == current[0] && path[1] == current[1]) {
                // If it does, add the adjacent n-tersection to the queue and set
                queue.offer(path);
                visited.add(path[0] + "," + path[1]);
            }
        }
    }
    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] path : paths) {
            if (current[0] + path[0] >= 0 && current[0] + path[0] < n && current[1] + path[1] >= 0 && current[1] + path[1] < n && !visited[current[0] + path[0]][current[1] + path[1]]) {
                queue.offer(new int[] {current[0] + path[0], current[1] + path[1]});
                visited[current[0] + path[0]][current[1] + path[1]] = true;
            }
        }
    }

    return "cannot be travelled";
}

