public static String convertDatesToWeekdays(String date) {
    String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    String[] dateArray = date.split(" ");
    int month = Integer.parseInt(dateArray[0]);
    int day = Integer.parseInt(dateArray[1]);
    int year = Integer.parseInt(dateArray[2]);
    int monthDay = Integer.parseInt(dateArray[1] + dateArray[2]);
    int weekday = (monthDay + (year % 100) + (year / 100) + ((year % 100) / 4) + ((year / 100) / 4) + (5 * (year / 100))) % 7;
    return String.format("%s %d, %d is a %s", months[month - 1], day, year, weekdays[weekday]);
}

public static String convertDatesToWeekdays(String date) {
    DateFormat df = new SimpleDateFormat("MM dd yyyy");
    String weekDay = df.format(new Date(date));
    switch (weekDay) {
        case "Sunday":
            return "Sunday";
        case "Monday":
            return "Monday";
        case "Tuesday":
            return "Tuesday";
        case "Wednesday":
            return "Wednesday";
        case "Thursday":
            return "Thursday";
        case "Friday":
            return "Friday";
        case "Saturday":
            return "Saturday";
        default:
            return "Invalid date";
    }
}

public static String convertDatesToWeekdays(String date) {
    // Parse the date to get the day, month, and year
    String[] dateParts = date.split(" ");
    int day = Integer.parseInt(dateParts[1]);
    int month = Integer.parseInt(dateParts[0]);
    int year = Integer.parseInt(dateParts[2]);

    // Create a LocalDate object from the date parts
    LocalDate dateObj = LocalDate.of(year, month, day);

    // Get the day of the week from the LocalDate object
    DayOfWeek dow = dateObj.getDayOfWeek();

    // Convert the day of the week to a string
    String weekday = dow.toString().toLowerCase();

    // Return the weekday of the date
    return String.format("%s, %s %s is a %s", month, day, year, weekday);
}

