public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int lowerSize = (int) (n * 0.05);
    int upperSize = (int) (n * 0.95) - lowerSize;
    int[] lower = Arrays.copyOfRange(arr, 0, lowerSize);
    int[] upper = Arrays.copyOfRange(arr, upperSize, n);
    double lowerSum = Array.stream(lower).sum();
    double upperSum = Array.stream(upper).sum();
    double mean = (lowerSum + upperSum) / (n - lowerSize - upperSize);
    return mean;
}

