public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    for (int i = 0; i < n / 2; i++) {
        boolean found = false;
        for (int j = n / 2; j < n; j++) {
            if ((arr[i] + arr[j]) % k == 0) {
                found = true;
                break;
            }
        }
        if (!found) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    int[] counts = new int[k];
    for (int i = 0; i < n; i++) {
        int sum = arr[i] + arr[(i + n/2) % n];
        if (sum % k != 0) return false;
        counts[sum % k]++;
    }
    int target = n/2;
    for (int count : counts) {
        if (count < target) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] sum = new int[n];
    for (int i = 0; i < n; i++) {
        sum[i] = (arr[i] % k) + (i > 0 ? sum[i - 1] : 0);
    }
    int target = sum[n - 1] / 2;
    int[] dp = new int[target + 1];
    for (int i = 0; i < n; i++) {
        for (int j = target; j >= sum[i]; j--) {
            dp[j] += dp[j - sum[i]];
        }
    }
    return dp[target] > 0;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    int[] count = new int[k];
    for (int i = 0; i < n; i++) {
        count[arr[i] % k]++;
    }
    int sum = 0;
    for (int j = 0; j < n; j++) {
        if (count[j] == 0) return false;
        if (j == 0) {
            sum += count[j];
        } else {
            if (sum % 2 == 0) {
                sum += count[j];
            } else {
                if (count[j] % 2 == 0) {
                    sum += count[j];
                } else {
                    return false;
                }
            }
        }
    }
    return sum % 2 == 0;
}

