    boolean[] used = new boolean[n];
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] + arr[j] % k == 0) {
                used[i] = used[j] = true;
                break;
            }
        }
    }
    for (boolean b : used) {
        if (!b) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (dist[u] != Integer.MAX_VALUE) {
                dist[v] = Math.min(dist[v], dist[u] + 1);
            }
        }
    }
    int time = 0;
    for (int i = 0; i < n; i++) {
        time += dist[i];
        if (hasApple[i]) {
            time -= dist[i];
        }
    }
    return time;
}

