        }
    }
    for (int[] edge : edges) {
        time += 1;
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    boolean[] visited = new boolean[n];
    int[] distance = new int[n];
    Arrays.fill(distance, Integer.MAX_VALUE);
    distance[0] = 0;

    for (int i = 0; i < n - 1; i++) {
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (distance[u] < Integer.MAX_VALUE && distance[v] > distance[u] + 1) {
                distance[v] = distance[u] + 1;
            }
        }
    }

    int minTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            minTime += distance[i];
        }
    }

    return minTime;
}

public String sortString(String s) {
    String result = "";
    while (s.length() > 0) {
        // Step 1: pick the smallest character from s and append it to the result
        char smallest = s.charAt(0);
        result += smallest;
        s = s.substring(1);

        // Step 2: pick the smallest character from s which is greater than the last appended character to the result and append it
        char smaller = Character.MAX_VALUE;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c > smallest && c < smaller) {
                smaller = c;
            }
        }
        if (smaller != Character.MAX_VALUE) {
            result += smaller;
            s = s.replace(String.valueOf(smaller), "");
        }

        // Step 3: pick the largest character from s and append it to the result
        char largest = s.charAt(s.length() - 1);
        result += largest;
        s = s.substring(0, s.length() - 1);

        // Step 4: pick the largest character from s which is smaller than the last appended character to the result and append it
        char larger = Character.MIN_VALUE;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < largest && c > larger) {
                larger = c;
            }
        }
        if (larger != Character.MIN_VALUE) {
            result += larger;
            s = s.replace(String.valueOf(larger), "");
        }
    }
    return result;
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder sb = new StringBuilder();
    while (sb.length() < chars.length) {
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] != sb.charAt(sb.length() - 1) && chars[i] != '\0') {
                sb.append(chars[i]);
            }
        }
        for (int i = chars.length - 1; i >= 0; i--) {
            if (chars[i] != sb.charAt(sb.length() - 1) && chars[i] != '\0') {
                sb.append(chars[i]);
            }
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    StringBuilder sb = new StringBuilder();
    while (sb.length() < s.length()) {
        char smallest = chars[0];
        char largest = chars[chars.length - 1];
        sb.append(smallest);
        for (int i = 1; i < chars.length; i++) {
            if (chars[i] > smallest && chars[i] < largest) {
                sb.append(chars[i]);
                break;
            }
        }
        for (int i = chars.length - 2; i >= 0; i--) {
            if (chars[i] < largest) {
                sb.append(largest);
                break;
            }
        }
    }
    return sb.toString();
}

