public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    for (int i = 0; i + k <= n; i++) {
        String sub = s.substring(i, i + k);
        if (!s.contains(sub)) {
            return false;
        }
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    int length = s.length();
    if (length < k) return false;
    int mask = (1 << k) - 1;
    for (int i = 0; i <= length - k; i++) {
        if ((s.charAt(i) & mask) != (s.charAt(i + k - 1) & mask)) return false;
    }
    return true;
}

