public int findMinFibonacciNumbers(int k) {
    int[] fib = {0, 1, 1};
    for (int i = 3; fib[i - 1] < k; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
    int count = 0;
    while (k > 0) {
        count++;
        k -= fib[count];
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int f1 = 1, f2 = 1, fn = 0;
    int count = 0;
    while (k > 0) {
        fn = f1 + f2;
        f1 = f2;
        f2 = fn;
        if (k-fn >= 0) {
            k -= fn;
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int[] fib = {1, 1};
    int i = 0;
    while (fib[i] < k) {
        int next = fib[i] + fib[i + 1];
        fib = Arrays.copyOf(fib, fib.length + 1);
        fib[i + 1] = next;
        i++;
    }
    int min = 0;
    while (fib[i] >= k) {
        min++;
        k -= fib[i];
        i--;
    }
    return min + 1;
}

public int findMinFibonacciNumbers(int k) {
    int dp[] = new int[k + 1];
    int F[] = new int[k + 1];
    F[0] = 1;
    F[1] = 1;
    for (int i = 0; i <= k; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    for (int i = 2; i <= k; i++) {
        for (int j = 1; j < i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j] + 1);
        }
        F[i] = F[i - 1] + F[i - 2];
    }
    return dp[k];
}

public int findMinFibonacciNumbers(int k) {
    int f0 = 0, f1 = 1, f2 = 1, min = Integer.MAX_VALUE;
    while (f0 < k) {
        min = Math.min(min, f0 + f1);
        f0 = f1;
        f1 = f2;
        f2 = f0 + f1;
    }
    return min;
}

