public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] freq = new int[26];
    List<Integer> indexes = new ArrayList<>();
    StringBuilder sb = new StringBuilder();
    int max = -1;

    for (int i = 0; i < n; i++) {
        freq[s.charAt(i) - 'a']++;
        if (freq[s.charAt(i) - 'a'] == 1) {
            indexes.add(i);
        }
        if (indexes.size() == n) {
            break;
        }
    }

    for (int i = 0; i < n; i++) {
        sb.append(s.charAt(i));
        if (freq[s.charAt(i) - 'a'] > 1) {
            int index = indexes.get(freq[s.charAt(i) - 'a'] - 2);
            sb.insert(index, s.substring(i, index));
            i = index;
            indexes.set(freq[s.charAt(i) - 'a'] - 2, i);
        }
    }

    max = Math.max(max, indexes.size());
    return max;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int[][] dp = new int[n][n];
    int max = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= i; j++) {
            if (i - j < 2) {
                dp[i][j] = 1;
            } else {
                dp[i][j] = 2;
                for (int k = j + 1; k <= i - 1; k++) {
                    if (s.charAt(j) != s.charAt(k) && s.charAt(i) != s.charAt(k)) {
                        dp[i][j] = Math.max(dp[i][j], dp[k - 1][j] + dp[i - k][k]);
                    }
                }
            }
            max = Math.max(max, dp[i][j]);
        }
    }
    return max;
}

