public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        sb.append((char)('a' + (k - i) % 26));
        k -= i;
    }
    return sb.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int curCharVal = k % 26 + 1;
        sb.append((char) ('a' + curCharVal - 1));
        k /= 26;
    }
    return sb.reverse().toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    while (n > 0) {
        sb.append((char)('a' + (k - 1) % 26));
        k = (k - 1) / 26;
        n--;
    }
    return sb.reverse().toString();
}

