public static int squarePermutations(int[] A) {
      int n = A.length;
      int[][] dp = new int[n][n];
      for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
          if (i == j) {
            dp[i][j] = 1;
          } else if (i + 1 == j) {
            if (Math.sqrt(A[i] + A[j]) % 1 == 0) {
              dp[i][j] = 1;
            } else {
              dp[i][j] = 0;
            }
          } else {
            dp[i][j] = dp[i][j - 1] + dp[i - 1][j - 1] - dp[i - 1][j - 1];
          }
        }
      }
      return dp[n - 1][n - 1];
    }

