public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    stack<Integer> s = new stack<Integer>();
    s.push(-1);
    for (int i = 0; i < n; i++) {
        while (s.peek() != -1 && heights[s.peek()] >= heights[i]) {
            s.pop();
        }
        left[i] = s.peek() + 1;
        s.push(i);
    }
    s.push(-1);
    for (int i = n - 1; i >= 0; i--) {
        while (s.peek() != -1 && heights[s.peek()] >= heights[i]) {
            s.pop();
        }
        right[i] = s.peek() + 1;
        s.push(i);
    }
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int maxArea = 0;
    int[] left = new int[n];
    int[] right = new int[n];
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[i] <= heights[stack.peek()]) {
            int top = stack.pop();
            right[top] = i;
        }
        if (!stack.isEmpty()) {
            left[i] = stack.peek();
        }
        stack.push(i);
    }

    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, (right[i] - left[i] - 1) * heights[i]);
    }

    return maxArea;
}

