public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }

    for (int i = 0; i < points.length; i++) {
        for (int j = 0; j < points.length; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }

    int area = 0;
    for (int i = 0; i < points.length; i++) {
        area += points[i][0] * points[i][1];
    }

    return area == 0 ? true : false;
}

public static boolean isBoomerang(int[][] points) {
    // Check if points has at least 3 elements
    if (points.length < 3) {
        return false;
    }

    // Sort the points by their x-coordinate
    Arrays.sort(points, (p1, p2) -> Integer.compare(p1[0], p2[0]));

    // Check if the points form a boomerang shape
    for (int i = 0; i < points.length - 2; i++) {
        int slope1 = points[i + 1][1] - points[i][1];
        int slope2 = points[i + 2][1] - points[i + 1][1];
        if (slope1 * slope2 > 0) {
            return false;
        }
    }

    return true;
}

