    int x3 = points[2][0], y3 = points[2][1];
    return ((x1*y2+x2*y3+x3*y1 == x2*y1+x3*y2+x1*y3) && (x1*y1+x2*y2+x3*y3 == x2*y2+x3*y3+x1*y1));
}

public static boolean isBoomerang(int[][] points) {
    int lowerX, upperX, lowerY, upperY;
    lowerX = upperX = points[0][0];
    lowerY = upperY = points[0][1];

    for (int[] point : points) {
        lowerX = Math.min(lowerX, point[0]);
        upperX = Math.max(upperX, point[0]);
        lowerY = Math.min(lowerY, point[1]);
        upperY = Math.max(upperY, point[1]);
    }

    return lowerX == upperX || lowerY == upperY;
}

