        if (ugly[i] == ugly[i2] * 2)
            i2++;
        if (ugly[i] == ugly[i3] * 3)
            i3++;
        if (ugly[i] == ugly[i5] * 5)
            i5++;
    }

    return ugly[n - 1];
}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;

    uglyNumbers[0] = 1;

    for (int i = 1; i < n; i++) {
        int min = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = min;
        if (min == nextMultipleOf2) {
            i2++;
            nextMultipleOf2 = uglyNumbers[i2] * 2;
        }
        if (min == nextMultipleOf3) {
            i3++;
            nextMultipleOf3 = uglyNumbers[i3] * 3;
        }
        if (min == nextMultipleOf5) {
            i5++;
            nextMultipleOf5 = uglyNumbers[i5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
    int i2 = 0, i3 = 0, i5 = 0;
    int[] dp = new int[n];
    dp[0] = 1;
    for (int i = 1; i < n; i++) {
        int n2 = dp[i2] * 2;
        int n3 = dp[i3] * 3;
        int n5 = dp[i5] * 5;
        dp[i] = Math.min(n2, Math.min(n3, n5));
        if (dp[i] == n2) i2++;
        if (dp[i] == n3) i3++;
        if (dp[i] == n5) i5++;
    }
    return dp[n - 1];
}

public static int calculateEnergy(String s) {
    int energy = 1;
    char prevChar = s.charAt(0);
    int longestStreak = 1;

    for (int i = 1; i < s.length(); i++) {
        char currChar = s.charAt(i);
        if (currChar == prevChar) {
            longestStreak++;
        } else {
            longestStreak = 1;
        }
        energy = Math.max(energy, longestStreak);
        prevChar = currChar;
    }

    return energy;
}

public static int calculateEnergy(String s) {
    int energy = 1;
    char currentChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char nextChar = s.charAt(i);
        if (currentChar == nextChar) {
            energy++;
        } else {
            energy = Math.max(energy, i - countChar(s, currentChar, 0, i - 1));
            currentChar = nextChar;
        }
    }
    return energy;
}

public static int calculateEnergy(String s) {
    int energy = 1;
    int maxEnergy = 1;
    char currentChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == currentChar) {
            energy++;
        } else {
            currentChar = c;
            energy = 1;
        }
        maxEnergy = Math.max(energy, maxEnergy);
    }
    return maxEnergy;
}

public static int calculateEnergy(String s) {
    int maxLength = 1;
    int length = 1;
    char currentChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == currentChar) {
            length++;
            if (length > maxLength) {
                maxLength = length;
            }
        } else {
            currentChar = c;
            length = 1;
        }
    }
    return maxLength;
}

public static int calculateEnergy(String s) {
    int energy = 1;
    int maxEnergy = 0;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            energy++;
        } else {
            energy = 1;
        }
        maxEnergy = Math.max(energy, maxEnergy);
    }

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort(Comparator.naturalOrder());
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result, new Comparator<Integer>() {
        @Override
        public int compare(Integer a, Integer b) {
            return Integer.toString(a).compareTo(Integer.toString(b));
        }
    });
    return result;
}

public static List<Integer> lexicalOrder(int n) {
      List<Integer> result = new ArrayList<>();
      for (int i = 1; i <= n; i++) {
          result.add(i);
      }
      Collections.sort(result, (a, b) -> {
          String sa = String.valueOf(a);
          String sb = String.valueOf(b);
          return sa.compareTo(sb);
      });
      return result;
  }

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 1; i <= n / 10; i++) {
        result.add(n % 10 * 10 + i);
    }
    return result;
}

