public static int minPerfectSquareSum(int n) {
      int minSquares = 0;
      int i = 1;
      while (i * i <= n) {
        minSquares++;
        n -= i * i;
        i++;
      }
      return minSquares;
    }

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int sqrt = (int)Math.sqrt(n);
        count++;
        n -= sqrt * sqrt;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    int i = 1;
    while (i * i <= n) {
        count++;
        n -= i * i;
        i++;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    // Initialize the number of perfect square numbers needed to sum up to n as n itself
    int numPerfectSquares = n;
    // Initialize the current perfect square number as 1
    int currentPerfectSquare = 1;

    // Loop until the current perfect square is less than or equal to the square root of n
    while (currentPerfectSquare <= Math.sqrt(n)) {
        // If the current perfect square is a divisor of n, decrement the number of perfect square numbers needed
        if (n % currentPerfectSquare == 0) {
            numPerfectSquares--;
        }
        // Increment the current perfect square by 1
        currentPerfectSquare++;
    }

    // Return the minimum number of perfect square numbers needed to sum up to n
    return numPerfectSquares;
}

public static int minPerfectSquareSum(int n) {
    int result = 0;
    int perfectSquare = 1;
    while (perfectSquare <= n) {
        result++;
        perfectSquare = perfectSquare * 2;
    }
    return result;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
        StringBuilder sb = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            sb.append(word.charAt(i));
        }
        result.append(sb).append(" ");
    }
    result.setLength(result.length() - 1);
    return result.toString();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedString = new StringBuilder();
    for (String word : words) {
        reversedString.append(new StringBuilder(word).reverse());
    }
    return reversedString.toString();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        char[] chars = word.toCharArray();
        sb.append(reverse(chars));
        if (i < words.length - 1) {
            sb.append(" ");
        }
    }
    return sb.toString();
}

